54	  ON public.expositora_movimentacoes (loja_id, produto_master_id, created_at DESC);
55	CREATE INDEX IF NOT EXISTS idx_expositora_mov_loja_data
56	  ON public.expositora_movimentacoes (loja_id, created_at DESC);
