684	-- ─────────────────────────────────────────────────────────────────────────────
685	-- 8) bipar_retirada_avulsa: contexto.destino = 'expositora' → a própria RPC
686	--    registra a movimentação de saída (motivo 'retirada_avulsa_exposicao');
687	--    o trigger credita a expositora. Frontend NÃO insere movimentação nesse caso
688	--    (resposta traz movimentacao_registrada = true).
689	--    Sem destino (default 'saida'): comportamento idêntico ao atual.
690	-- ─────────────────────────────────────────────────────────────────────────────
691	
692	CREATE OR REPLACE FUNCTION public.bipar_retirada_avulsa(p_uid text, p_quantidade numeric, p_contexto jsonb DEFAULT '{}'::jsonb)
693	 RETURNS jsonb
694	 LANGUAGE plpgsql
695	 SECURITY DEFINER
696	 SET search_path TO 'public'
697	AS $function$
698	DECLARE
699	  v_etiqueta            public.etiquetas_qr%ROWTYPE;
700	  v_user_id             uuid := auth.uid();
701	  v_user_nome           text;
702	  v_loja_id             integer;
703	  v_referencia_tipo     text;
704	  v_referencia_id       text;
705	  v_payload             jsonb;
706	  v_disponivel_apos     numeric;
707	  v_status_anterior     text;
708	  v_status_novo         text;
709	  v_pid_text            text;
710	  v_pid_int             integer;
711	  v_lote_uuid           uuid;
712	  v_produto_nome        text;
713	  v_lote_codigo         text;
714	  v_lote_validade       date;
715	  v_qty_interna         numeric;
716	  -- destino expositora
717	  v_destino             text;
718	  v_loja_eff            integer;
719	  v_est_ant             numeric;
720	  v_mov_registrada      boolean := false;
721	BEGIN
722	  IF p_quantidade IS NULL OR p_quantidade <= 0 THEN
723	    RETURN jsonb_build_object('ok', false, 'erro', 'Quantidade deve ser maior que zero');
724	  END IF;
725	
726	  v_loja_id         := NULLIF(p_contexto->>'loja_id','')::integer;
727	  v_referencia_tipo := p_contexto->>'referencia_tipo';
728	  v_referencia_id   := p_contexto->>'referencia_id';
729	  v_payload         := p_contexto->'payload';
730	  v_destino         := COALESCE(NULLIF(p_contexto->>'destino',''), 'saida');
731	
732	  IF v_destino NOT IN ('saida','expositora') THEN
733	    RETURN jsonb_build_object('ok', false, 'erro', 'Destino invalido: ' || v_destino);
734	  END IF;
735	
736	  SELECT * INTO v_etiqueta FROM public.etiquetas_qr WHERE uid = p_uid FOR UPDATE;
737	
738	  -- ===== BACKFILL legacy: etiqueta sem row mas com payload no QR =====
739	  IF NOT FOUND THEN
740	    IF v_payload IS NULL THEN
741	      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao encontrada (sem payload para backfill)');
742	    END IF;
743	    v_pid_text := COALESCE(v_payload->>'pid', v_payload->>'p');
744	    IF v_pid_text IS NULL OR v_pid_text = '' THEN
745	      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e payload sem produto');
746	    END IF;
747	    v_pid_int     := v_pid_text::integer;
748	    v_lote_uuid   := NULLIF(COALESCE(v_payload->>'lid', v_payload->>'l'),'')::uuid;
749	    v_qty_interna := COALESCE(NULLIF(COALESCE(v_payload->>'qty', v_payload->>'q'),'')::numeric, 1);
750	
751	    SELECT nome INTO v_produto_nome FROM public.produtos_master WHERE id = v_pid_int;
752	    IF v_lote_uuid IS NOT NULL THEN
753	      SELECT codigo, data_validade INTO v_lote_codigo, v_lote_validade FROM public.lotes WHERE id = v_lote_uuid;
754	    END IF;
755	
756	    INSERT INTO public.etiquetas_qr (
757	      uid, produto_master_id, lote_id, embalagem_nome, quantidade_interna,
758	      quantidade_disponivel, consumida_inteira,
759	      produto_nome_snapshot, lote_codigo_snapshot, lote_validade_snapshot,
760	      loja_origem_id, loja_atual_id, status, tipo_embalagem,
761	      backfilled, qr_payload
762	    ) VALUES (
763	      p_uid, v_pid_int, v_lote_uuid,
764	      COALESCE(v_payload->>'emb', v_payload->>'n'),
765	      v_qty_interna, v_qty_interna, false,
766	      v_produto_nome, v_lote_codigo, v_lote_validade,
767	      NULL, v_loja_id, 'gerada',
768	      COALESCE(v_payload->>'tipo', v_payload->>'t', 'caixa'),
769	      true, v_payload
770	    )
771	    RETURNING * INTO v_etiqueta;
772	
773	    INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
774	      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata)
775	      VALUES (p_uid, 'backfilled', 'backfill', NULL, 'gerada',
776	      v_loja_id, v_user_id, COALESCE((SELECT raw_user_meta_data->>'nome' FROM auth.users WHERE id = v_user_id), NULL),
777	      v_referencia_tipo, v_referencia_id,
778	      jsonb_build_object('etapa_origem', 'retirada_avulsa', 'payload', v_payload));
779	  END IF;
780	
781	  IF v_etiqueta.consumida_inteira OR v_etiqueta.status = 'consumida' THEN
782	    RETURN jsonb_build_object('ok', false,
783	      'erro', format('Etiqueta %s ja foi consumida totalmente', p_uid),
784	      'etiqueta', to_jsonb(v_etiqueta));
785	  END IF;
786	  IF v_etiqueta.status = 'descartada' THEN
787	    RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta descartada', 'etiqueta', to_jsonb(v_etiqueta));
788	  END IF;
789	
790	  IF p_quantidade > v_etiqueta.quantidade_disponivel THEN
791	    RETURN jsonb_build_object('ok', false,
792	      'erro', format('Container so tem %s disponivel (pediu %s)', v_etiqueta.quantidade_disponivel, p_quantidade),
793	      'etiqueta', to_jsonb(v_etiqueta));
794	  END IF;
795	
796	  -- destino expositora exige loja conhecida — validar ANTES de qualquer escrita
797	  v_loja_eff := COALESCE(v_loja_id, v_etiqueta.loja_atual_id);
798	  IF v_destino = 'expositora' AND v_loja_eff IS NULL THEN
799	    RETURN jsonb_build_object('ok', false, 'erro', 'Destino expositora exige loja conhecida (contexto ou etiqueta)');
800	  END IF;
801	
802	  v_disponivel_apos := v_etiqueta.quantidade_disponivel - p_quantidade;
803	  v_status_anterior := v_etiqueta.status;
804	  v_status_novo := CASE
805	    WHEN v_disponivel_apos = 0 THEN 'consumida'
806	    WHEN v_disponivel_apos < v_etiqueta.quantidade_interna THEN 'aberta'
807	    ELSE v_status_anterior
808	  END;
809	
810	  UPDATE public.etiquetas_qr SET
811	    quantidade_disponivel = v_disponivel_apos,
812	    consumida_inteira     = (v_disponivel_apos = 0),
813	    status                = v_status_novo,
814	    loja_atual_id         = COALESCE(v_loja_id, loja_atual_id)
815	  WHERE uid = p_uid RETURNING * INTO v_etiqueta;
816	
817	  SELECT COALESCE(raw_user_meta_data->>'nome', email) INTO v_user_nome FROM auth.users WHERE id = v_user_id;
818	
819	  INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
820	    loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata)
821	    VALUES (p_uid,
822	      CASE WHEN v_disponivel_apos = 0 THEN 'consumida_total' ELSE 'retirada_avulsa' END,
823	      'consumo', v_status_anterior, v_status_novo,
824	      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
825	      jsonb_build_object(
826	        'quantidade_retirada', p_quantidade,
827	        'quantidade_disponivel_antes', v_etiqueta.quantidade_interna - v_disponivel_apos + p_quantidade,
828	        'quantidade_disponivel_apos', v_disponivel_apos,
829	        'consumida_inteira', v_etiqueta.consumida_inteira,
830	        'destino', v_destino));
831	
832	  -- destino expositora: movimentação de saída do estoque registrada AQUI
833	  -- (trigger credita a expositora na mesma transação)
834	  IF v_destino = 'expositora' THEN
835	    SELECT quantidade_atual INTO v_est_ant
836	      FROM public.estoque
837	     WHERE produto_master_id = v_etiqueta.produto_master_id AND loja_id = v_loja_eff
838	     FOR UPDATE;
839	    v_est_ant := COALESCE(v_est_ant, 0);
840	
841	    INSERT INTO public.movimentacoes (
842	      produto_master_id, tipo_movimentacao, quantidade,
843	      quantidade_anterior, quantidade_nova, motivo, observacoes,
844	      data_movimentacao, loja_id, lote_id, etiqueta_qr_uid
845	    ) VALUES (
846	      v_etiqueta.produto_master_id, 'saida', p_quantidade,
847	      v_est_ant, v_est_ant - p_quantidade,
848	      'retirada_avulsa_exposicao',
849	      format('Retirada avulsa pra vitrine — UID %s', p_uid),
850	      NOW(), v_loja_eff, v_etiqueta.lote_id, p_uid
851	    );
852	    v_mov_registrada := true;
853	  END IF;
854	
855	  RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta),
856	    'quantidade_retirada', p_quantidade, 'quantidade_disponivel', v_disponivel_apos,
857	    'consumida_inteira', v_etiqueta.consumida_inteira,
858	    'status_anterior', v_status_anterior, 'status_novo', v_status_novo,
859	    'destino', v_destino, 'movimentacao_registrada', v_mov_registrada);
860	END;
861	$function$;
