917	-- ─────────────────────────────────────────────────────────────────────────────
918	-- 10) atualizar_estoque_e_alertas: alertas passam a comparar o TOTAL EM LOJA
919	--     (estoque câmara + expositora) — evita alarme falso quando o estoque
920	--     simplesmente subiu pra vitrine. Upsert de estoque inalterado.
921	--     Ramo legacy (produto_id) inalterado.
922	-- ─────────────────────────────────────────────────────────────────────────────
923	
924	CREATE OR REPLACE FUNCTION public.atualizar_estoque_e_alertas()
925	 RETURNS trigger
926	 LANGUAGE plpgsql
927	 SET search_path TO 'public', 'pg_temp'
928	AS $function$
929	DECLARE
930	    estoque_atual DECIMAL(10,3);
931	    estoque_minimo DECIMAL(10,3);
932	    expositora_qtd DECIMAL(10,3);
933	    total_loja DECIMAL(10,3);
934	BEGIN
935	    -- Scenario 1: New System (Master ID)
936	    IF NEW.produto_master_id IS NOT NULL THEN
937	        -- Upsert into estoque using (produto_master_id, loja_id)
938	        -- We assume 'estoque_produto_master_loja_unique' constraint exists on (produto_master_id, loja_id)
939	        INSERT INTO estoque (produto_master_id, quantidade_atual, ultima_movimentacao, ultimo_usuario_id, loja_id)
940	        VALUES (NEW.produto_master_id, NEW.quantidade_nova, NEW.data_movimentacao, NEW.usuario_id, NEW.loja_id)
941	        ON CONFLICT (produto_master_id, loja_id)
942	        DO UPDATE SET
943	            quantidade_atual = EXCLUDED.quantidade_atual,
944	            ultima_movimentacao = EXCLUDED.ultima_movimentacao,
945	            ultimo_usuario_id = EXCLUDED.ultimo_usuario_id,
946	            updated_at = NOW();
947	
948	        -- Check Alerts (sobre o TOTAL em loja: câmara + expositora)
949	        SELECT quantidade_atual, quantidade_minima
950	        INTO estoque_atual, estoque_minimo
951	        FROM estoque
952	        WHERE produto_master_id = NEW.produto_master_id AND loja_id = NEW.loja_id;
953	
954	        SELECT quantidade INTO expositora_qtd
955	        FROM expositora_estoque
956	        WHERE produto_master_id = NEW.produto_master_id AND loja_id = NEW.loja_id;
957	
958	        total_loja := COALESCE(estoque_atual, 0) + COALESCE(expositora_qtd, 0);
959	
960	        IF estoque_atual IS NOT NULL AND estoque_minimo IS NOT NULL THEN
961	            IF total_loja <= 0 THEN
962	                INSERT INTO alertas_estoque (produto_master_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
963	                VALUES (NEW.produto_master_id, NEW.loja_id, 'sem_estoque', total_loja, estoque_minimo);
964	            ELSIF total_loja <= (estoque_minimo * 0.5) THEN
965	                INSERT INTO alertas_estoque (produto_master_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
966	                VALUES (NEW.produto_master_id, NEW.loja_id, 'critico', total_loja, estoque_minimo);
967	            ELSIF total_loja <= estoque_minimo THEN
968	                INSERT INTO alertas_estoque (produto_master_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
969	                VALUES (NEW.produto_master_id, NEW.loja_id, 'baixo', total_loja, estoque_minimo);
970	            END IF;
971	        END IF;
972	
973	    -- Scenario 2: Legacy System (Product ID)
974	    ELSIF NEW.produto_id IS NOT NULL THEN
975	        -- Upsert into estoque using (produto_id, loja_id)
976	        INSERT INTO estoque (produto_id, quantidade_atual, ultima_movimentacao, ultimo_usuario_id, loja_id)
977	        VALUES (NEW.produto_id, NEW.quantidade_nova, NEW.data_movimentacao, NEW.usuario_id, NEW.loja_id)
978	        ON CONFLICT (produto_id, loja_id)
979	        DO UPDATE SET
980	            quantidade_atual = EXCLUDED.quantidade_atual,
981	            ultima_movimentacao = EXCLUDED.ultima_movimentacao,
982	            ultimo_usuario_id = EXCLUDED.ultimo_usuario_id,
983	            updated_at = NOW();
984	
985	        -- Check Alerts
986	        SELECT quantidade_atual, quantidade_minima
987	        INTO estoque_atual, estoque_minimo
988	        FROM estoque
989	        WHERE produto_id = NEW.produto_id AND loja_id = NEW.loja_id;
990	
991	        IF estoque_atual IS NOT NULL AND estoque_minimo IS NOT NULL THEN
992	             IF estoque_atual <= 0 THEN
993	                INSERT INTO alertas_estoque (produto_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
994	                VALUES (NEW.produto_id, NEW.loja_id, 'sem_estoque', estoque_atual, estoque_minimo);
995	            ELSIF estoque_atual <= (estoque_minimo * 0.5) THEN
996	                INSERT INTO alertas_estoque (produto_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
997	                VALUES (NEW.produto_id, NEW.loja_id, 'critico', estoque_atual, estoque_minimo);
998	            ELSIF estoque_atual <= estoque_minimo THEN
999	                INSERT INTO alertas_estoque (produto_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
1000	                VALUES (NEW.produto_id, NEW.loja_id, 'baixo', estoque_atual, estoque_minimo);
1001	            END IF;
1002	        END IF;
1003	
1004	    END IF;
