/**
 * Helpers puros do fluxo Expositora (vitrine) — Scanner / Saída Avulsa.
 *
 * Modelo: `estoque` = câmara fria/congelado · `expositora_estoque` = exposto
 * no salão. Quando o destino de uma retirada é a expositora, as RPCs
 * (`bipar_etiqueta` etapa 'exposicao' e `bipar_retirada_avulsa` com
 * contexto.destino='expositora') criam a movimentação de saída SERVER-SIDE
 * na mesma transação que credita a vitrine. Nesses casos o frontend NÃO pode
 * inserir em `movimentacoes` — duplicaria a baixa do estoque.
 */

/** Destino de uma retirada de estoque feita pela loja. */
export type SaidaDestino = 'saida' | 'expositora';

/** Subconjunto relevante da resposta de bipar_retirada_avulsa. */
export interface BipRetiradaResponse {
  ok?: boolean;
  /** true quando a RPC já registrou a movimentação de saída server-side. */
  movimentacao_registrada?: boolean;
}

/**
 * Decide se o frontend deve PULAR o INSERT manual em `movimentacoes` após
 * `bipar_retirada_avulsa`. Quando a RPC responde `movimentacao_registrada:
 * true` (destino expositora), a saída já foi gravada dentro da transação da
 * RPC (motivo 'retirada_avulsa_exposicao') — inserir de novo duplicaria a
 * baixa do estoque.
 */
export function shouldSkipManualMovimentacao(
  resp: BipRetiradaResponse | null | undefined,
): boolean {
  return resp?.movimentacao_registrada === true;
}

import { describe, it, expect } from 'vitest';
import { shouldSkipManualMovimentacao } from '../expositora';

describe('shouldSkipManualMovimentacao', () => {
  it('retorna true quando a RPC registrou a movimentação server-side (destino expositora)', () => {
    expect(
      shouldSkipManualMovimentacao({ ok: true, movimentacao_registrada: true }),
    ).toBe(true);
  });

  it('retorna false quando movimentacao_registrada vem false (destino saída — fluxo atual)', () => {
    expect(
      shouldSkipManualMovimentacao({ ok: true, movimentacao_registrada: false }),
    ).toBe(false);
  });

  it('retorna false quando o campo não existe (RPC antiga / resposta sem destino)', () => {
    expect(shouldSkipManualMovimentacao({ ok: true })).toBe(false);
  });

  it('retorna false pra resposta nula ou indefinida', () => {
    expect(shouldSkipManualMovimentacao(null)).toBe(false);
    expect(shouldSkipManualMovimentacao(undefined)).toBe(false);
  });

  it('exige true estrito — valores truthy não estritos não pulam o insert', () => {
    expect(
      shouldSkipManualMovimentacao({
        movimentacao_registrada: 1 as unknown as boolean,
      }),
    ).toBe(false);
    expect(
      shouldSkipManualMovimentacao({
        movimentacao_registrada: 'true' as unknown as boolean,
      }),
    ).toBe(false);
  });
});

