                    loja_id: selectedStore.id,
                    referencia_tipo: 'scanner_exposicao',
                    payload: item.data,
                },
            });
            const rpc = rpcRaw as { ok: boolean; erro?: string; quantidade_exposta?: number } | null;

            if (rpcErr || !rpc) {
                errorCount++;
                const msg = rpcErr?.message || 'Sem retorno do servidor';
                setScannedItems(prev => prev.map(i => i.id === item.id ? { ...i, status: 'error' as const, error: msg } : i));
                continue;
            }
            if (rpc.ok) {
                successCount++;
                unidadesExpostas += Number(rpc.quantidade_exposta ?? 0);
                setScannedItems(prev => prev.map(i => i.id === item.id
                    ? {
                        ...i,
                        status: 'success' as const,
                        error: undefined,
                        etiquetaStatus: 'consumida',
                        etiqueta: i.etiqueta ? { ...i.etiqueta, quantidade_disponivel: 0 } : i.etiqueta,
                    }
                    : i));
            } else if (isDuplicateBipError(rpc.erro)) {
                // Mesma semântica do lote atual: status não permite — âmbar, não vermelho.
                duplicateCount++;
                setScannedItems(prev => prev.map(i => i.id === item.id
                    ? { ...i, status: 'duplicate' as const, error: rpc.erro || 'Etiqueta não pode ir pra expositora' }
                    : i));
            } else {
                errorCount++;
                setScannedItems(prev => prev.map(i => i.id === item.id
                    ? { ...i, status: 'error' as const, error: rpc.erro || 'Bip rejeitado' }
                    : i));
            }
        }

        if (successCount > 0) {
            playSuccessSound();
            toast({
                title: `${successCount} ${successCount === 1 ? 'item exposto' : 'itens expostos'} na vitrine`,
                description: `${unidadesExpostas} unidades saíram do estoque pra expositora.`,
            });
            setTimeout(() => {
                setScannedItems(prev => prev.filter(i => i.status !== 'success'));
            }, 3000);
        }

        if (duplicateCount > 0) {
            toast({
                title: `${duplicateCount} não ${duplicateCount === 1 ? 'pôde' : 'puderam'} ir pra vitrine`,
                description: "Caixas em âmbar estão num status que não permite exposição — nada foi duplicado.",
            });
        }

        if (errorCount > 0) {
            playErrorSound();
            toast({
                title: "Atenção",
                description: `${errorCount} ${errorCount === 1 ? 'caixa não pôde' : 'caixas não puderam'} ser exposta${errorCount === 1 ? '' : 's'}. Veja o detalhe na lista.`,
                variant: "destructive"
            });
        }
    } catch (e) {
        // Falha geral (rede, permissão) — marca os itens restantes como error.
        handleError(e, { domain: 'scanner', operation: 'processBatchExposicao', showToast: false });
        const msg = (e as Error).message || 'Erro desconhecido';
        const failedIds = new Set(itemsToProcess.map(i => i.id));
        setScannedItems(prev => prev.map(i =>
            failedIds.has(i.id) && i.status !== 'success' && i.status !== 'duplicate'
                ? { ...i, status: 'error' as const, error: msg }
                : i
        ));
        playErrorSound();
        toast({ title: "Erro crítico", description: msg, variant: "destructive" });
    } finally {
        setIsProcessing(false);
    }
};

const totalItems = scannedItems.length;
const totalUnitsProcess = scannedItems.reduce((acc, item) => (item.status !== 'success' && item.status !== 'duplicate') ? acc + (item.data.qty || 0) : acc, 0);

